def test_core_bbox_matches_beam_top_exactly():
    for profile, expected_beam_top in [('compact', 150.0), ('universal', 199.0)]:
        layout = plan_layout(default_config(profile))
        assert math.isclose(layout['core_bbox_mm'][2], expected_beam_top, abs_tol=1e-6)
        assert math.isclose(layout['printed_bbox_mm'][2], expected_beam_top, abs_tol=1e-6)
